parts=['# cycle257 宣言案内\n\n全引数は各コード型に記したとおり全称量化される。日本語の共通条件と個別説明を合わせて読む。完全な elaborated 型は [alltypes-final.txt](alltypes-final.txt)。固定の実I45 family以外への一般化は明記した箇所だけ。\n']
count=0
for m in v.joinpath('modules.txt').read_text().splitlines():
 s=Path('lean/Yulang/'+m+'.lean').read_text();parts.append('## '+m+'\n\n'+scopes[m]+'\n')
 for found in re.finditer(r'^\s*((?:noncomputable\s+)?(theorem|def|abbrev)\s+(\w+)[\s\S]*?)(?=\s*:=|\s+where|\n\s*\|)',s,re.M):
  header,kind,name=found.group(1,2,3);count+=1
  statement=verbs.get(name,'このmoduleの共通条件で用いる具体的な表現・判定を定義する。' if kind!='theorem' else None)
  if statement is None:raise ValueError((m,name))
  parts.append('### `'+name+'`\n\n'+statement+' 上記の共通対象・範囲と、次の明示前提の下で読む。\n\n```lean\n'+header.strip()+'\n```\n')
v.joinpath('declaration-guide.md').write_text('\n'.join(parts));print('Guide entries',count)
